-- Fresh predictive namespace only. Applied before DDL witnesses are armed.
SET ROLE __OWNER__;
ALTER TABLE predictive_jobs_v4.jobs ADD COLUMN retry_id uuid,ADD COLUMN retry_actor text,ADD COLUMN retry_grant jsonb,ADD COLUMN retry_until timestamptz;
CREATE TABLE predictive_jobs_v4.retry_requests(control uuid PRIMARY KEY,tenant text NOT NULL,job_id uuid NOT NULL REFERENCES predictive_jobs_v4.jobs(id),reviewer text NOT NULL CHECK(octet_length(reviewer) BETWEEN 1 AND 512),expected_grant bigint NOT NULL CHECK(expected_grant>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION predictive_jobs_v4._retry_request_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP<>'INSERT' OR NOT EXISTS(SELECT 1 FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current()) THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_REQUEST_IMMUTABLE';END IF;RETURN NEW;END $$;
CREATE TRIGGER predictive_retry_request_write BEFORE INSERT OR UPDATE OR DELETE ON predictive_jobs_v4.retry_requests FOR EACH ROW EXECUTE FUNCTION predictive_jobs_v4._retry_request_guard();
CREATE TRIGGER predictive_retry_request_truncate BEFORE TRUNCATE ON predictive_jobs_v4.retry_requests FOR EACH STATEMENT EXECUTE FUNCTION predictive_jobs_v4._retry_request_guard();
ALTER TABLE predictive_jobs_v4.retry_requests ENABLE ALWAYS TRIGGER predictive_retry_request_write;
ALTER TABLE predictive_jobs_v4.retry_requests ENABLE ALWAYS TRIGGER predictive_retry_request_truncate;
REVOKE ALL ON TABLE predictive_jobs_v4.retry_requests FROM PUBLIC;
REVOKE ALL ON FUNCTION predictive_jobs_v4._retry_request_guard() FROM PUBLIC;
CREATE OR REPLACE FUNCTION predictive_jobs_v4._public(j predictive_jobs_v4.jobs) RETURNS jsonb LANGUAGE sql STABLE STRICT AS $$
 SELECT jsonb_build_object('id',j.id::text,'tenantId',j.tenant,'actorId',j.actor_id,'commandId',j.command_id::text,'action',j.action,'requestHash',j.request_hash,'businessKey',j.business_key,'sealedCommand',j.sealed_command,'grantRevision',j.grant_revision::text,'status',j.status,'leaseLive',j.lease_until>clock_timestamp(),'cancelRequested',j.cancel_requested,'externalStarted',j.external_started,'attempts',j.attempts,'result',j.result,'errorCode',j.error_code,'publicationId',j.publication_id::text,'retryId',j.retry_id::text,'retryActor',j.retry_actor,'retryPending',j.retry_grant IS NOT NULL,'createdAt',j.created_at,'updatedAt',j.updated_at)
$$;
CREATE OR REPLACE FUNCTION predictive_jobs_v4.claim_v4(tenant text,owner uuid,token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;BEGIN
 PERFORM predictive_jobs_v4._assert(tenant,true);IF owner IS NULL OR token IS NULL THEN RAISE EXCEPTION 'PREDICTIVE_QUEUE_INPUT';END IF;
 SELECT * INTO j FROM predictive_jobs_v4.jobs q WHERE q.tenant=claim_v4.tenant AND q.next_attempt<=clock_timestamp() AND (q.status IN('ACCEPTED','RETRY') OR q.status='RUNNING' AND q.lease_until<=clock_timestamp()) ORDER BY q.ordinal LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN NULL;END IF;
 INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE predictive_jobs_v4.jobs SET status='RUNNING',worker_id=owner,claim_token=token,fence=fence+1,lease_until=clock_timestamp()+interval '30 seconds',updated_at=clock_timestamp() WHERE id=j.id RETURNING * INTO j;DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();
 RETURN predictive_jobs_v4._public(j)||jsonb_build_object('sealedGrant',j.sealed_grant,'grantUntil',j.grant_until,'owner',j.worker_id::text,'token',j.claim_token::text,'fence',j.fence::text,'leaseUntil',j.lease_until,'sealedRetryGrant',j.retry_grant,'retryUntil',j.retry_until);
END $$;
CREATE OR REPLACE FUNCTION predictive_jobs_v4.lock_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint,deadline timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;BEGIN j:=predictive_jobs_v4._claim(tenant,wanted,owner,token,fence,grant_revision);
 IF j.retry_grant IS NOT NULL THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_CONTROL_PENDING';END IF;
 IF deadline IS NULL OR deadline<=clock_timestamp() OR j.grant_until<=clock_timestamp() THEN RAISE EXCEPTION 'PREDICTIVE_QUEUE_AUTH_EXPIRED';END IF;
 INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE predictive_jobs_v4.jobs SET auth_deadline=deadline WHERE id=wanted;DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();RETURN predictive_jobs_v4._public(j);
END $$;
CREATE FUNCTION predictive_jobs_v4.review_candidate_v4(tenant text,wanted uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;BEGIN PERFORM predictive_jobs_v4._assert(tenant,false);SELECT * INTO j FROM predictive_jobs_v4.jobs q WHERE q.tenant=review_candidate_v4.tenant AND q.id=wanted;IF NOT FOUND OR j.retry_id IS NULL AND j.status<>'HUMAN_REVIEW' THEN RETURN NULL;END IF;RETURN predictive_jobs_v4._public(j);END $$;
CREATE FUNCTION predictive_jobs_v4.request_retry_v4(tenant text,wanted uuid,expected_grant bigint,control uuid,reviewer text,sealed jsonb,until_time timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;prior predictive_jobs_v4.retry_requests;BEGIN PERFORM predictive_jobs_v4._assert(tenant,false);
 IF control IS NULL OR reviewer IS NULL OR reviewer='' OR octet_length(reviewer)>512 THEN RAISE EXCEPTION 'PREDICTIVE_INDEPENDENT_RETRY_REQUIRED';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('predictive-retry:'||tenant||':'||control::text,0));
 SELECT * INTO STRICT j FROM predictive_jobs_v4.jobs q WHERE q.tenant=request_retry_v4.tenant AND q.id=wanted FOR UPDATE;IF reviewer=j.actor_id THEN RAISE EXCEPTION 'PREDICTIVE_INDEPENDENT_RETRY_REQUIRED';END IF;
 SELECT * INTO prior FROM predictive_jobs_v4.retry_requests q WHERE q.control=request_retry_v4.control;
 IF FOUND THEN IF prior.tenant IS DISTINCT FROM tenant OR prior.job_id IS DISTINCT FROM wanted OR prior.reviewer IS DISTINCT FROM reviewer OR prior.expected_grant IS DISTINCT FROM expected_grant THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_CONFLICT';END IF;IF j.retry_id IS DISTINCT FROM control THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_SUPERSEDED';END IF;RETURN predictive_jobs_v4._public(j);END IF;
 IF expected_grant IS NULL OR j.grant_revision<>expected_grant OR j.status<>'HUMAN_REVIEW' OR j.cancel_requested OR sealed IS NULL OR jsonb_typeof(sealed)<>'object' OR octet_length(sealed::text)>65536 OR until_time IS NULL OR until_time<=clock_timestamp() THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_CONFLICT';END IF;
 INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());INSERT INTO predictive_jobs_v4.retry_requests(control,tenant,job_id,reviewer,expected_grant) VALUES(control,tenant,wanted,reviewer,expected_grant);UPDATE predictive_jobs_v4.jobs SET retry_id=control,retry_actor=reviewer,retry_grant=sealed,retry_until=until_time,status='ACCEPTED',fence=fence+1,worker_id=NULL,claim_token=NULL,lease_until=NULL,auth_deadline=NULL,next_attempt=clock_timestamp(),updated_at=clock_timestamp() WHERE id=wanted RETURNING * INTO j;DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();RETURN predictive_jobs_v4._public(j);
END $$;
CREATE FUNCTION predictive_jobs_v4.lock_retry_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint,deadline timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;BEGIN j:=predictive_jobs_v4._claim(tenant,wanted,owner,token,fence,grant_revision);
 IF j.cancel_requested OR j.retry_id IS NULL OR j.retry_actor IS NULL OR j.retry_actor=j.actor_id OR j.retry_grant IS NULL OR j.retry_until IS NULL OR j.retry_until<=clock_timestamp() OR deadline IS NULL OR deadline<=clock_timestamp() THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_AUTH_REQUIRED';END IF;
 RETURN predictive_jobs_v4._public(j);
END $$;
CREATE FUNCTION predictive_jobs_v4.defer_retry_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;BEGIN j:=predictive_jobs_v4._claim(tenant,wanted,owner,token,fence,grant_revision);IF j.retry_grant IS NULL THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_CONFLICT';END IF;
 INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE predictive_jobs_v4.jobs SET status='HUMAN_REVIEW',retry_grant=NULL,retry_until=NULL,error_code='PREDICTIVE_RETRY_REVIEW_REQUIRED',worker_id=NULL,claim_token=NULL,lease_until=NULL,auth_deadline=NULL,updated_at=clock_timestamp() WHERE id=wanted RETURNING * INTO j;DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();RETURN predictive_jobs_v4._public(j);
END $$;
CREATE FUNCTION predictive_jobs_v4.prepare_retry_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint,deadline timestamptz,command uuid,revision bigint,root bytea,operations jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,state_map_v1,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;before_job jsonb;b jsonb;r jsonb;a jsonb;o jsonb;receipt jsonb;BEGIN
 PERFORM state_map_v1.read_head_v1(tenant);PERFORM predictive_jobs_v4.lock_retry_v4(tenant,wanted,owner,token,fence,grant_revision,deadline);j:=predictive_jobs_v4._claim(tenant,wanted,owner,token,fence,grant_revision);before_job:=predictive_jobs_v4._sdk(j);
 IF before_job->>'status' IS DISTINCT FROM 'HUMAN_REVIEW' THEN RAISE EXCEPTION 'PREDICTIVE_NOT_HUMAN_REVIEW';END IF;
 receipt:=state_map_v1.apply_delta_v1(tenant,command,revision,root,operations);PERFORM predictive_jobs_v4.lock_retry_v4(tenant,wanted,owner,token,fence,grant_revision,deadline);b:=predictive_jobs_v4._sdk(j);r:=predictive_jobs_v4._state(tenant,'receipt','predictive_retry:'||j.business_key||':'||j.retry_id::text)->'value';
 IF b->>'status' IS DISTINCT FROM 'WAITING_AUTH' OR b->>'planDigest' IS DISTINCT FROM before_job->>'planDigest' OR b->'context' IS DISTINCT FROM before_job->'context' OR (b->>'grantRevision')::bigint<>(before_job->>'grantRevision')::bigint+1 OR b->>'attempts' IS DISTINCT FROM '0' OR r->>'format' IS DISTINCT FROM 'IDMS_PREDICTIVE_MAP_V4_1' OR r->>'tenantId' IS DISTINCT FROM tenant OR r->>'key' IS DISTINCT FROM j.business_key OR r->>'commandId' IS DISTINCT FROM j.command_id::text OR r->>'requestHash' IS DISTINCT FROM j.request_hash OR r->>'planDigest' IS DISTINCT FROM b->>'planDigest' OR r->>'controlId' IS DISTINCT FROM j.retry_id::text OR r->>'reviewerId' IS DISTINCT FROM j.retry_actor OR r->>'originalActor' IS DISTINCT FROM j.actor_id THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_PROOF';END IF;
 a:=predictive_jobs_v4._state(tenant,'audit',r->>'auditEventId')->'value';o:=predictive_jobs_v4._state(tenant,'audit_order',lpad(r->>'auditPosition',20,'0'))->'value';
 IF a->>'tenantId' IS DISTINCT FROM tenant OR o->>'tenantId' IS DISTINCT FROM tenant OR a->>'eventId' IS DISTINCT FROM r->>'auditEventId' OR a->>'eventId' IS DISTINCT FROM o->>'eventId' OR a->>'hash' IS DISTINCT FROM r->>'auditHash' OR a->>'action' IS DISTINCT FROM 'PREDICTIVE_RETRY_REVIEWED' OR a->>'actorId' IS DISTINCT FROM j.retry_actor OR a->'metadata'->>'originalActor' IS DISTINCT FROM j.actor_id OR a->'metadata'->>'controlId' IS DISTINCT FROM j.retry_id::text OR a->'metadata'->>'jobKey' IS DISTINCT FROM j.business_key OR a->'metadata'->>'commandId' IS DISTINCT FROM j.command_id::text THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_AUDIT';END IF;
 INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE predictive_jobs_v4.jobs SET status='WAITING_AUTH',attempts=0,error_code='PREDICTIVE_ORIGINAL_REAUTH_REQUIRED',retry_grant=NULL,retry_until=NULL,worker_id=NULL,claim_token=NULL,lease_until=NULL,auth_deadline=NULL,updated_at=clock_timestamp() WHERE id=wanted;DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();RETURN receipt;
END $$;
CREATE OR REPLACE FUNCTION predictive_jobs_v4.close_command_console_v4(tenant text,actor text,command uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;BEGIN
 PERFORM predictive_jobs_v4._assert(tenant,false);IF actor IS NULL OR octet_length(actor)<1 OR octet_length(actor)>512 OR command IS NULL THEN RAISE EXCEPTION 'PREDICTIVE_QUEUE_INPUT';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('console:'||predictive_jobs_v4._business_key(tenant,actor,command),0));
 INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());INSERT INTO predictive_jobs_v4.command_fences(tenant,actor_id,command_id) VALUES(tenant,actor,command) ON CONFLICT ON CONSTRAINT console_command_fence_pk DO NOTHING;
 SELECT * INTO j FROM predictive_jobs_v4.jobs q WHERE q.tenant=close_command_console_v4.tenant AND q.actor_id=actor AND q.command_id=command FOR UPDATE;
 IF FOUND AND j.status NOT IN('COMMITTED','FAILED','CANCELLED') AND NOT j.external_started THEN UPDATE predictive_jobs_v4.jobs SET cancel_requested=true,status='WAITING_AUTH',retry_grant=NULL,retry_until=NULL,error_code='PREDICTIVE_CANCEL_AUTH_REQUIRED',fence=j.fence+1,worker_id=NULL,claim_token=NULL,lease_until=NULL,auth_deadline=NULL,updated_at=clock_timestamp() WHERE id=j.id RETURNING * INTO j;END IF;
 DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();RETURN jsonb_build_object('commandId',command::text,'acceptanceClosed',true,'recoveryRequired',coalesce(j.external_started AND j.status NOT IN('COMMITTED','FAILED','CANCELLED'),false),'job',CASE WHEN j.id IS NULL THEN NULL ELSE predictive_jobs_v4._public(j) END);
END $$;
CREATE OR REPLACE FUNCTION predictive_jobs_v4.authorize_v4(tenant text,actor text,wanted uuid,expected_grant bigint,sealed jsonb,until_time timestamptz,cancel boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;BEGIN
 PERFORM predictive_jobs_v4._assert(tenant,false);SELECT * INTO STRICT j FROM predictive_jobs_v4.jobs q WHERE q.id=wanted AND q.tenant=authorize_v4.tenant AND q.actor_id=actor FOR UPDATE;
 IF j.status IN('COMMITTED','FAILED','CANCELLED') THEN RETURN predictive_jobs_v4._public(j);END IF;
 IF cancel IS NULL OR expected_grant IS NULL OR j.grant_revision<>expected_grant OR sealed IS NULL OR until_time IS NULL OR until_time<=clock_timestamp() THEN RAISE EXCEPTION 'PREDICTIVE_QUEUE_GRANT_CONFLICT';END IF;
 IF cancel AND j.external_started THEN RAISE EXCEPTION 'PREDICTIVE_CREATION_RECOVERY_REQUIRED';END IF;
 IF j.retry_grant IS NOT NULL THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_CONTROL_PENDING';END IF;
 IF j.status='HUMAN_REVIEW' AND NOT cancel THEN RAISE EXCEPTION 'PREDICTIVE_RETRY_REQUIRED';END IF;
 INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE predictive_jobs_v4.jobs SET sealed_grant=sealed,grant_revision=j.grant_revision+1,grant_until=until_time,cancel_requested=cancel_requested OR cancel,status='ACCEPTED',worker_id=NULL,claim_token=NULL,lease_until=NULL,auth_deadline=NULL,fence=fence+1,next_attempt=clock_timestamp(),updated_at=clock_timestamp() WHERE id=wanted RETURNING * INTO j;DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();RETURN predictive_jobs_v4._public(j);
END $$;
CREATE OR REPLACE FUNCTION predictive_jobs_v4.cancel_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint,deadline timestamptz,cancel_command uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,state_map_v1,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;b jsonb;r jsonb;a jsonb;o jsonb;BEGIN
 PERFORM state_map_v1.read_head_v1(tenant);PERFORM predictive_jobs_v4.lock_v4(tenant,wanted,owner,token,fence,grant_revision,deadline);j:=predictive_jobs_v4._claim(tenant,wanted,owner,token,fence,grant_revision);IF NOT j.cancel_requested OR j.external_started THEN RAISE EXCEPTION 'PREDICTIVE_CREATION_RECOVERY_REQUIRED';END IF;
 b:=predictive_jobs_v4._state(tenant,'predictive_job',j.business_key)->'value';
 IF b IS NOT NULL AND b<>'null'::jsonb THEN
 b:=predictive_jobs_v4._sdk(j);r:=predictive_jobs_v4._state(tenant,'receipt','predictive_cancel:'||j.business_key)->'value';
 IF b->>'status' IS DISTINCT FROM 'CANCELLED' OR r->>'format' IS DISTINCT FROM 'IDMS_PREDICTIVE_MAP_V4_1' OR r->>'tenantId' IS DISTINCT FROM tenant OR r->>'key' IS DISTINCT FROM j.business_key OR r->>'commandId' IS DISTINCT FROM j.command_id::text OR r->>'requestHash' IS DISTINCT FROM j.request_hash OR r->>'planDigest' IS DISTINCT FROM b->>'planDigest' THEN RAISE EXCEPTION 'PREDICTIVE_SDK_CANCEL_REQUIRED';END IF;
 a:=predictive_jobs_v4._state(tenant,'audit',r->>'auditEventId')->'value';o:=predictive_jobs_v4._state(tenant,'audit_order',lpad(r->>'auditPosition',20,'0'))->'value';
 IF a->>'tenantId' IS DISTINCT FROM tenant OR o->>'tenantId' IS DISTINCT FROM tenant OR a->>'hash' IS DISTINCT FROM r->>'auditHash' OR a->>'eventId' IS DISTINCT FROM r->>'auditEventId' OR a->>'eventId' IS DISTINCT FROM o->>'eventId' OR a->>'action' IS DISTINCT FROM 'PREDICTIVE_COMMAND_CANCELLED' OR a->>'actorId' IS DISTINCT FROM j.actor_id OR a->'metadata'->>'commandId' IS DISTINCT FROM j.command_id::text OR a->'metadata'->>'jobKey' IS DISTINCT FROM j.business_key THEN RAISE EXCEPTION 'PREDICTIVE_CANCEL_AUDIT';END IF;
 END IF;
 INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE predictive_jobs_v4.jobs SET status='CANCELLED',result=NULL,error_code='CANCELLED',worker_id=NULL,claim_token=NULL,lease_until=NULL,auth_deadline=NULL,updated_at=clock_timestamp() WHERE id=wanted RETURNING * INTO j;DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();RETURN predictive_jobs_v4._public(j);
END $$;
CREATE FUNCTION predictive_jobs_v4.prepare_cancel_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint,deadline timestamptz,command uuid,revision bigint,root bytea,operations jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,state_map_v1,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;b jsonb;r jsonb;before_job jsonb;BEGIN
 PERFORM state_map_v1.read_head_v1(tenant);PERFORM predictive_jobs_v4.lock_v4(tenant,wanted,owner,token,fence,grant_revision,deadline);j:=predictive_jobs_v4._claim(tenant,wanted,owner,token,fence,grant_revision);IF NOT j.cancel_requested OR j.external_started THEN RAISE EXCEPTION 'PREDICTIVE_CREATION_RECOVERY_REQUIRED';END IF;before_job:=predictive_jobs_v4._sdk(j);IF before_job->>'status' NOT IN('PENDING','WAITING_AUTH','HUMAN_REVIEW') THEN RAISE EXCEPTION 'PREDICTIVE_CANCEL_TERMINAL';END IF;
 r:=state_map_v1.apply_delta_v1(tenant,command,revision,root,operations);b:=predictive_jobs_v4._sdk(j);IF b->>'planDigest' IS DISTINCT FROM before_job->>'planDigest' OR b->'context' IS DISTINCT FROM before_job->'context' THEN RAISE EXCEPTION 'PREDICTIVE_CANCEL_PLAN_CHANGED';END IF;PERFORM predictive_jobs_v4.cancel_v4(tenant,wanted,owner,token,fence,grant_revision,deadline,command);RETURN r;
END $$;
REVOKE ALL ON FUNCTION predictive_jobs_v4.review_candidate_v4(text,uuid),predictive_jobs_v4.request_retry_v4(text,uuid,bigint,uuid,text,jsonb,timestamptz),predictive_jobs_v4.lock_retry_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz),predictive_jobs_v4.defer_retry_v4(text,uuid,uuid,uuid,bigint,bigint),predictive_jobs_v4.prepare_retry_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,bigint,bytea,jsonb),predictive_jobs_v4.prepare_cancel_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,bigint,bytea,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION predictive_jobs_v4.review_candidate_v4(text,uuid),predictive_jobs_v4.request_retry_v4(text,uuid,bigint,uuid,text,jsonb,timestamptz) TO __INGRESS__;
GRANT EXECUTE ON FUNCTION predictive_jobs_v4.lock_retry_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz),predictive_jobs_v4.defer_retry_v4(text,uuid,uuid,uuid,bigint,bigint),predictive_jobs_v4.prepare_retry_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,bigint,bytea,jsonb),predictive_jobs_v4.prepare_cancel_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,bigint,bytea,jsonb) TO __WORKER__;
RESET ROLE;
